modify_existing.before:
it(
  '[AC-F1-08ai-ACCESS#1] 只读和其他资金权限没有勾选或批量通过；审核权限与超管可勾选，未勾选不出现批量栏',
  { timeout: 90_000 },
  async () => {
    for (const permissions of [
      { isSuper: false, permissions: ['fund.view'] },
      {
        isSuper: false,
        permissions: [
          'fund.view',
          'payout.execute',
          'payout.manual_entry',
          'export',
          'config.business',
        ],
      },
    ]) {
      const server = serverFor();
      await mount(server, permissions);
      expect(within(main()).queryAllByRole('checkbox')).toEqual([]);
      expect(buttons(main(), '批量通过')).toEqual([]);
      expect(server.writes()).toEqual([]);
      cleanup();
    }
    for (const permissions of [REVIEW, { isSuper: true, permissions: [] }]) {
      const server = serverFor();
      await mount(server, permissions);
      expect(buttons(main(), '批量通过')).toEqual([]);
      for (const item of server.state) expect(checkbox(item).checked).toBe(false);
      await select([server.state[0]!]);
      expect(disabled(button(main(), '批量通过'))).toBe(false);
      assertNoOtherActions();
      expect(server.writes()).toEqual([]);
      cleanup();
    }
  },
);

modify_existing.after:
it(
  '[AC-F1-08ai-ACCESS#1] 只读没有勾选或批量通过；其他资金权限（含 payout.manual_entry）没有【批量通过】，只有待执行单可勾（F1-08al）；审核权限与超管可勾选，未勾选不出现批量栏',
  { timeout: 90_000 },
  async () => {
    for (const permissions of [
      { isSuper: false, permissions: ['fund.view'] },
      {
        isSuper: false,
        permissions: [
          'fund.view',
          'payout.execute',
          'payout.manual_entry',
          'export',
          'config.business',
        ],
      },
    ]) {
      const server = permissions.permissions.includes('payout.manual_entry')
        ? serverFor(samples())
        : serverFor();
      await mount(server, permissions);
      if (permissions.permissions.includes('payout.manual_entry')) {
        expect(
          server.state
            .filter((item) =>
              within(rowOf(main(), item.out_biz_no))
                .queryAllByRole('checkbox')
                .some((node) => !disabled(node)),
            )
            .map((item) => item.withdrawal_id),
        ).toEqual(
          server.state
            .filter((item) => item.status === 'APPROVED')
            .map((item) => item.withdrawal_id),
        );
      } else {
        expect(within(main()).queryAllByRole('checkbox')).toEqual([]);
      }
      expect(buttons(main(), '批量通过')).toEqual([]);
      expect(server.writes()).toEqual([]);
      cleanup();
    }
    for (const permissions of [REVIEW, { isSuper: true, permissions: [] }]) {
      const server = serverFor();
      await mount(server, permissions);
      expect(buttons(main(), '批量通过')).toEqual([]);
      for (const item of server.state) expect(checkbox(item).checked).toBe(false);
      await select([server.state[0]!]);
      expect(disabled(button(main(), '批量通过'))).toBe(false);
      assertNoOtherActions();
      expect(server.writes()).toEqual([]);
      cleanup();
    }
  },
);
